import{_ as t,c as i,o as n,ae as l}from"./chunks/framework.Bi6zybwU.js";const g=JSON.parse('{"title":"Single Line Text Field","description":"Single Line Text Field","frontmatter":{"title":"Single Line Text Field","description":"Single Line Text Field"},"headers":[],"relativePath":"guide/field-types/single-line-text-field.md","filePath":"guide/field-types/single-line-text-field.md"}'),a={name:"guide/field-types/single-line-text-field.md"};function o(s,e,d,r,h,p){return n(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="single-line-text-field" tabindex="-1">Single Line Text Field <a class="header-anchor" href="#single-line-text-field" aria-label="Permalink to &quot;Single Line Text Field&quot;">​</a></h1><p>You can construct the data type of a column by hovering over or from the &quot;Table Configuration&quot; settings of the specific column. The &quot;Single Line Text Field&quot; is for columns with text data. You can decide the data type right from the start when you add a column to the table. From your dashboard, go to the <strong>Ninja Tables plugin → Tables <strong>(the table where you want to add Column)</strong> → Add Column</strong>.</p><ul><li>A pop-up form will appear, and you will see the available <strong>Data Type</strong> here. You can choose from the various data types listed in the below screenshot. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Data-Type.png" alt="Data-Type"> The Single Line Text field is a single textbox that&#39;s most useful for collecting one-word answers and short phrases. This data type will display text in a single-line format.</li><li>Go to the <strong>Data Type</strong> option and select the **Single Line Text Field **type of the column.</li><li>Now a new column with data type has been added to the table. If you want to see the data type works or not, click the pencil icon for the row and find the corresponding column&#39;s data type.</li></ul><h2 id="html-in-single-line-text-field" tabindex="-1">HTML In Single Line Text Field <a class="header-anchor" href="#html-in-single-line-text-field" aria-label="Permalink to &quot;HTML In Single Line Text Field&quot;">​</a></h2><p>Note that, Single Line Text Field is also <strong>HTML</strong> supported. So, not just plain texts, you can also display HTML in the table cell. The process is the same. Select the data type as single line text field and simply paste the desired HTML code in the blank text box. For example, we&#39;ve used <h2>Hello Ninja</h2> here. <img src="https://ninjatables.com/wp-content/uploads/2023/08/HTML-in-single-line-text-field.png" alt="HTML in single line text field"> Now, update the row and go to the <strong>Preview</strong> of the table and you will see the Single Line text Field has supported HTML. <img src="https://ninjatables.com/wp-content/uploads/2023/08/HTML-supported-in-single-line-text-field-1024x704.png" alt="HTML supported in single line text field"> The text size can be customized using HTML as well. You can easily add a Single Line Text Field to your column. And after you&#39;re done creating the table, you can change the data type anytime.</p>',5)])])}const u=t(a,[["render",o]]);export{g as __pageData,u as default};
